#include "City.h"
#include <algorithm>
#include <cmath>
#include <iostream>
#include <limits>
#include <stdexcept>
using namespace yoru;
namespace {
int checks=0;
void expect(bool ok,const std::string& message){checks++;if(!ok)throw std::runtime_error(message);}
bool near(double a,double b,double tolerance=1e-5){return std::abs(a-b)<tolerance;}
Building& b(City& c,Position p){return *c.state.tiles.at(p).building;}
void put(City& c,Position p,Kind kind,int residents=0){Building v;v.kind=kind;v.residents=residents;v.stock=commissioningStock(kind);c.state.tiles[p].building=v;}
City ground(){City c;c.reset(true);for(int x=0;x<=8;x++){auto& t=c.state.tiles[{x,1}];t.road=t.power=t.water=true;}put(c,{0,0},Kind::Exchange);put(c,{1,0},Kind::Reactor);put(c,{2,0},Kind::Waterworks);put(c,{3,0},Kind::Clinic);put(c,{4,0},Kind::Market);put(c,{6,0},Kind::Capsule,32);put(c,{7,0},Kind::Office);c.evaluate();return c;}
void invariants(City& c){auto before=serialize(c.state);auto forecast=c.totals;c.evaluate();expect(serialize(c.state)==before,"Views and forecasts preserve memory, valves, reserves and pipe condition");expect(near(forecast.waterLost,c.totals.waterLost),"Leak dispatch is deterministic");double loss=0;for(auto& e:c.edges){expect(e.load>=-1e-6&&e.load<=e.capacity+1e-5,"Physical edge capacity includes inlet flow before leakage");loss+=e.loss;}expect(near(loss,c.totals.waterLost),"All leaked water is counted exactly once");expect(c.totals.waterDelivered+c.totals.waterCharging+c.totals.waterLost<=c.totals.waterSupply+1e-5,"Sources cover water delivered, stored and lost, including booster cascades");expect(c.totals.powerDelivered+c.totals.powerCharging<=c.totals.powerSupply+1e-5,"Protected reserves create no electrical supply");}
}
int main(){try{
    auto c=ground();auto home=Position{6,0};c.state.tiles[{4,1}].pipeCondition=.3;c.evaluate();expect(c.totals.waterLost>0,"A worn flowing pipe leaks actual water");expect(near(b(c,{2,0}).dispatched,c.totals.waterDelivered+c.totals.waterCharging+c.totals.waterLost),"Waterworks dispatch accounts for every lost and delivered unit");invariants(c);
    auto authored=serialize(c.state);expect(!c.servicePipe({4,1})&&serialize(c.state)==authored,"A full pipe repair needs isolation and a rejected repair changes nothing");c.beginEdit();expect(c.toggleValve({4,1}),"Pipes have explicit isolation valves");expect(near(b(c,home).water,0)&&near(c.totals.waterLost,0),"Isolation stops both the leak and downstream delivery on a single feed");expect(c.servicePipe({4,1}),"A closed pipe can be repaired");expect(near(c.at({4,1})->pipeCondition,1)&&c.at({4,1})->waterClosed,"Repair retains isolation until explicitly reopened");c.undo();expect(serialize(c.state)==authored,"One undo restores the pre-isolation pipe and all finance");
    for(int x=3;x<=5;x++)c.state.tiles[{x,2}].water=true;c.evaluate();c.toggleValve({4,1});expect(b(c,home).water>.99,"A parallel pipe loop carries demand while the damaged branch is isolated");invariants(c);c.servicePipe({4,1});c.toggleValve({4,1});expect(near(c.totals.waterLost,0),"Repair and reopening eliminate the loss");c.toggleValve({4,1});c.erase({4,1},Layer::Water);expect(serialize(deserialize(serialize(c.state)))==serialize(c.state),"Removing an isolated pipe also removes its valve state");
    auto reserves=ground();put(reserves,{0,2},Kind::Battery);b(reserves,{0,2}).stored=200;reserves.setReserve({0,2},.5);reserves.toggle({1,0});expect(near(reserves.totals.powerDelivered,0),"Normal consumers cannot draw a protected battery reserve");expect(near(reserves.totals.powerProtected,200),"Protected energy is reported in physical storage units");reserves.configure(home,1,0);expect(b(reserves,home).power>.99&&b(reserves,{3,0}).power<.01,"Critical consumers release reserves while normal demand remains blocked");double stored=b(reserves,{0,2}).stored,discharged=b(reserves,{0,2}).discharge;reserves.step();expect(near(b(reserves,{0,2}).stored,stored-discharged/6),"Emergency electrical discharge debits the exact MWh quantity");invariants(reserves);expect(!reserves.setReserve(home,.5)&&!reserves.setReserve({0,2},1)&&!reserves.setReserve({0,2},std::numeric_limits<double>::quiet_NaN()),"Invalid reserve controls are rejected");
    auto tank=ground();put(tank,{0,2},Kind::Reservoir);b(tank,{0,2}).stored=300;tank.setReserve({0,2},.5);tank.toggle({2,0});expect(near(tank.totals.waterDelivered,0),"Normal consumers cannot drain protected water");tank.configure(home,1,0);expect(b(tank,home).water>.99&&b(tank,{3,0}).water<.01,"Water reserve release follows actual receiving priority");invariants(tank);
    City gravity;gravity.reset(true);gravity.connect({3,1,0},{3,1,2},ConnectorKind::Riser);gravity.buildDeck({3,0,2});put(gravity,{3,0,2},Kind::Reservoir);b(gravity,{3,0,2}).stored=80;gravity.buildDeck({2,1,1});gravity.state.tiles[{2,1,1}].water=true;gravity.buildDeck({2,0,1});put(gravity,{2,0,1},Kind::Capsule,20);gravity.evaluate();expect(near(b(gravity,{3,0,2}).power,0)&&b(gravity,{3,0,2}).discharge>0&&b(gravity,{2,0,1}).water>.99,"An elevated tank delivers real gravity water during an electrical outage");expect(b(gravity,{2,0,1}).head==2,"An unpowered elevated tank cannot manufacture an extra level of pressure");invariants(gravity);
    auto vertical=ground();vertical.buildCore({3,1,1});for(int x=2;x<=6;x++){auto& t=vertical.state.tiles[{x,1,1}];t.deck=t.walk=t.power=t.water=true;}vertical.buildDeck({3,0,1});put(vertical,{3,0,1},Kind::Capsule,32);vertical.connect({2,1,0},{2,1,1},ConnectorKind::Riser);vertical.connect({3,1,0},{3,1,1},ConnectorKind::Stairs);auto upper=Position{3,0,1};vertical.evaluate();expect(b(vertical,upper).escapeRoutes==1&&b(vertical,upper).blackoutExit&&!b(vertical,upper).blackoutStepFree,"A single stair is one ground exit and no passive step-free route");vertical.connect({6,1,0},{6,1,1},ConnectorKind::Lift);size_t lift=vertical.state.connectors.size()-1;expect(b(vertical,upper).escapeRoutes==2,"Independent stairs and a lift provide two separate ground routes");auto snapshot=serialize(vertical.state);auto probe=vertical.probeConnector(lift);expect(probe&&probe->lostWalk==0&&probe->lostStepFree==32,"A lift outage probe distinguishes general access from step-free loss");expect(serialize(vertical.state)==snapshot,"Outage probes cannot mutate, advance or consume the authored city");
    for(int y=1;y<=4;y++)vertical.route({6,y,0},Layer::Road);vertical.connect({6,4,0},{6,1,1},ConnectorKind::Ramp);vertical.evaluate();expect(b(vertical,upper).blackoutStepFree,"A connected passive ramp supplies a blackout step-free exit");expect(vertical.probeConnector(lift)->lostStepFree==0,"A parallel ramp removes the lift's single point of failure");expect(!vertical.probeConnector(9999),"Unknown transfer probes fail without mutating the city");
    auto shared=ground();shared.buildCore({3,1,1});shared.buildDeck({3,0,1});put(shared,{3,0,1},Kind::Capsule,20);for(auto p:{Position{3,1,1},{3,2,1},{2,2,1},{4,2,1}}){shared.buildDeck(p);shared.state.tiles[p].walk=true;}for(int x=2;x<=4;x++){auto& t=shared.state.tiles[{x,2,0}];t.road=t.power=true;}shared.connect({2,2,0},{2,2,1},ConnectorKind::Lift);shared.connect({4,2,0},{4,2,1},ConnectorKind::Lift);shared.evaluate();expect(b(shared,{3,0,1}).escapeRoutes==1,"Two powered shafts behind one common upper approach still provide only one independent ground route");for(auto p:{Position{3,0,1},{4,0,1},{4,1,1}}){shared.buildDeck(p);shared.state.tiles[p].walk=true;}shared.evaluate();expect(b(shared,{3,0,1}).escapeRoutes==2,"A second physical highwalk approach creates an independent alternative");
    auto cascade=ground();cascade.connect({5,1,0},{5,1,7},ConnectorKind::Riser);cascade.buildCore({2,1,7});for(int z:{3,6,7}){for(int x=2;x<=5;x++){auto& t=cascade.state.tiles[{x,1,z}];t.deck=t.water=t.power=true;}cascade.buildDeck({2,0,z});}put(cascade,{2,0,3},Kind::Booster);put(cascade,{2,0,6},Kind::Booster);put(cascade,{2,0,7},Kind::Capsule);for(auto& [p,t]:cascade.state.tiles)if(t.water&&p.z>0)t.pipeCondition=.65;cascade.evaluate();expect(b(cascade,{2,0,7}).water>.99&&cascade.totals.waterLost>0,"Demand-driven booster cascades compensate real pipe losses when source and route capacity permit");invariants(cascade);
    City core;core.reset(true);core.buildCore({0,0,2});for(int z=1;z<=2;z++){core.buildDeck({1,0,z});put(core,{1,0,z},Kind::Capsule,20);}core.evaluate();double incoming=0;for(auto flow:core.bearingFlows)if(flow.to==Position{0,0,0})incoming+=flow.load;expect(near(core.bearing[{0,0,0}].load,incoming+3),"Visible bearing-flow arrows carry the actual cumulative foundation load");auto before=serialize(core.state);auto broken=core.probeCore({0,0,0});expect(broken&&broken->unsafeResidents==40,"Foundation probes identify every dependent household");expect(serialize(core.state)==before,"Structural failure probes preserve all modules and residents");core.buildCore({2,0,2});core.evaluate();expect(core.probeCore({0,0,0})->unsafeResidents==0,"A second reachable bearing path supports the stack after the first core fails");expect(!core.probeCore({9,9}),"A non-core cannot be probed as a bearing member");
    auto debt=ground();debt.toggle({3,0});double care=b(debt,home).careDebt;for(int i=0;i<8;i++)debt.step();expect(b(debt,home).careDebt>care,"Unmet care persists beyond the current forecast");debt.toggle({3,0});care=b(debt,home).careDebt;debt.step();expect(b(debt,home).careDebt<care,"Delivered care gradually clears the household backlog");
    City waiting;waiting.reset(true);for(int x=0;x<=8;x++){auto& t=waiting.state.tiles[{x,1}];t.road=t.power=t.water=true;}put(waiting,{0,0},Kind::Exchange);put(waiting,{1,0},Kind::Reactor);put(waiting,{2,0},Kind::Waterworks);for(int x=3;x<=5;x++)put(waiting,{x,0},Kind::Tower,180);put(waiting,{6,0},Kind::Clinic);b(waiting,{6,0}).condition=.13;b(waiting,{5,0}).careDebt=1;waiting.evaluate();std::map<Position,double> visits;for(auto& j:waiting.journeys)if(j.purpose==JourneyPurpose::Care)visits[j.from]+=j.people;double urgent=visits[{5,0}],ordinary=std::max(visits[{3,0}],visits[{4,0}]);expect(urgent>ordinary,"Finite clinic appointments prioritise accumulated need instead of map order");invariants(waiting);
    auto commute=ground();commute.state.tiles.erase({7,0});for(int x=9;x<=38;x++){auto& t=commute.state.tiles[{x,1}];t.road=t.power=t.water=true;}put(commute,{38,0},Kind::Office);b(commute,{38,0}).priority=0;commute.evaluate();expect(b(commute,home).travelCost>25,"Fatigue uses the actual mean cost of assigned work journeys");double freshWorkers=commute.totals.pedestrianTrips;commute.step();expect(b(commute,home).fatigue>0,"Long routes accumulate household fatigue on real ticks");b(commute,home).fatigue=1;commute.evaluate();expect(commute.totals.pedestrianTrips<freshWorkers,"Exhausted households supply fewer workers without double booking");invariants(commute);
    auto empty=ground();b(empty,home).residents=0;b(empty,home).enabled=false;empty.evaluate();empty.step();expect(near(b(empty,home).careDebt,0)&&near(b(empty,home).leisureDebt,0)&&near(b(empty,home).fatigue,0),"An empty home cannot accumulate fictional residents' unmet care or fatigue");
    auto saved=serialize(vertical.state);auto restored=deserialize(saved);expect(serialize(restored)==saved,"Schema five round-trips pipes, reserves and household memory");for(int i=0;i<6;i++){auto bad=saved;if(i==0)bad["tiles"][0]["pipeCondition"]=-1;if(i==1){bad["tiles"][0]["water"]=false;bad["tiles"][0]["waterClosed"]=true;}for(auto& t:bad["tiles"])if(t.contains("building")){if(i==2)t["building"]["fatigue"]=2;if(i==3)t["building"]["careDebt"]=-1;if(i==4)t["building"]["reserve"]=.9;if(i==5)t["building"]["reserve"]=.25;break;}bool rejected=false;try{deserialize(bad);}catch(...){rejected=true;}expect(rejected,"Invalid resilience state is rejected atomically");}
    auto legacy=saved;legacy["version"]=4;for(auto& t:legacy["tiles"]){t.erase("pipeCondition");t.erase("waterClosed");if(t.contains("building"))for(auto key:{"fatigue","careDebt","leisureDebt","reserve"})t["building"].erase(key);}auto migrated=deserialize(legacy);expect(migrated.tiles.size()==vertical.state.tiles.size()&&migrated.connectors.size()==vertical.state.connectors.size(),"V4 migration retains authored geometry and transfers");for(auto& [p,t]:migrated.tiles){expect(near(t.pipeCondition,1)&&!t.waterClosed,"Old pipes start sound and open");if(t.building)expect(near(t.building->fatigue,0)&&near(t.building->reserve,0),"Old households and stores receive neutral new defaults");}
    City demo;demo.reset();for(int tick=0;tick<30;tick++){invariants(demo);demo.step();}expect(demo.totals.population>1000&&demo.totals.careDebt>=0,"Starter city remains viable under the deeper dependencies");
    std::cout<<"PASS "<<checks<<" resilience, pipe-loss, reserve and household-memory checks\n";return 0;
}catch(const std::exception& e){std::cerr<<"FAIL after "<<checks<<" checks: "<<e.what()<<'\n';return 1;}}
